-- Generated by scripts/export_sqlite_to_postgres.py
BEGIN;


-- Xóa các bảng cũ để tránh xung đột cấu trúc
DROP TABLE IF EXISTS audit_logs CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS bookings CASCADE;
DROP TABLE IF EXISTS departures CASCADE;
DROP TABLE IF EXISTS tours CASCADE;
DROP TABLE IF EXISTS users CASCADE;



CREATE TABLE IF NOT EXISTS users (
	id VARCHAR(36) NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	role VARCHAR(30) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
)

;

CREATE TABLE IF NOT EXISTS tours (
	id VARCHAR(36) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	tour_type VARCHAR(50) NOT NULL, 
	description TEXT, 
	duration_minutes INTEGER NOT NULL, 
	base_price FLOAT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id)
)

;

CREATE TABLE IF NOT EXISTS departures (
	id VARCHAR(36) NOT NULL, 
	tour_id VARCHAR(36) NOT NULL, 
	departure_date DATE NOT NULL, 
	max_capacity INTEGER NOT NULL, 
	booked_capacity INTEGER NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tour_id) REFERENCES tours (id)
)

;

CREATE TABLE IF NOT EXISTS bookings (
	id VARCHAR(36) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	departure_id VARCHAR(36) NOT NULL, 
	customer_id VARCHAR(36) NOT NULL, 
	guest_count INTEGER NOT NULL, 
	pickup_location VARCHAR(255) NOT NULL, 
	total_amount FLOAT NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(departure_id) REFERENCES departures (id), 
	FOREIGN KEY(customer_id) REFERENCES users (id)
)

;

CREATE TABLE IF NOT EXISTS audit_logs (
	id VARCHAR(36) NOT NULL, 
	actor_user_id VARCHAR(36), 
	action VARCHAR(80) NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(36) NOT NULL, 
	detail TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_user_id) REFERENCES users (id)
)

;

